  metrics=[['Sayfa hızı', 'Ürün ve ödeme sayfaları ne kadar hızlı açılıyor', 'Cihaz ve bağlantıya göre değişir'], ['Sepet tamamlama', 'Sepete ekleyenlerden kaçı siparişe ulaşıyor', 'Ödeme yöntemi ve trafik kaynağıyla birlikte okunur'], ['Hata kayıtları', 'Ödeme veya sipariş adımlarında kaç hata oluştu', 'Hatanın kaynağı eklenti mi, sunucu mu ayrıştırılmalıdır']],
